static CompletableFuture<Pot> borrowAsync(PotLender lender) {
    CompletableFuture<Pot> result = new CompletableFuture<>();
    // 1. ask for a pot; the library calls back on its own thread
    Ticket ticket = lender.borrow((pot, error) -> {
        // 2. complete exactly once, with a value or an error
        if (error != null) result.completeExceptionally(error);
        else result.complete(pot);
    });
    return result;
}

