// Java equivalent: a CompletableFuture that cancels the call when it is cancelled
static CompletableFuture<Recipe> lookupAsync(RecipeSite site, String dish) {
    CompletableFuture<Recipe> result = new CompletableFuture<>();
    Call call = site.lookup(dish, (recipe, error) -> {
        if (error != null) result.completeExceptionally(error);
        else result.complete(recipe);
    });
    result.whenComplete((v, e) -> { if (result.isCancelled()) call.cancel(); });
    return result;
}
